atch":"VA user ID"},{"vaUserId":64,"vaName":"Starnesy","sourceUrl":"https://ufl.virtualarena.app/users/Starnesy","teamId":"USA","playerId":"1790190669844","displayName":"Starnesy","newProfile":false,"rosterId":"intl-USA-3","match":"VA user ID"}]')) SELECT CASE WHEN EXISTS(SELECT 1 FROM international_roster_audit WHERE id='va-international-rosters-20261111-complete') OR ((SELECT COUNT(*) FROM international_rosters WHERE competition_id='ufl-internationals' AND active=1)=60 AND (SELECT COUNT(*) FROM expected_roster e JOIN international_rosters r ON r.id=json_extract(e.value,'$.id') WHERE r.competition_id='ufl-internationals' AND r.active=1 AND r.team_id=json_extract(e.value,'$.teamId') AND r.player_id=json_extract(e.value,'$.playerId') AND r.display_name=json_extract(e.value,'$.name'))=60 AND NOT EXISTS(SELECT 1 FROM expected_players e JOIN league_va_player_links l ON l.va_user_id=json_extract(e.value,'$.vaUserId') OR l.player_id=json_extract(e.value,'$.playerId') WHERE l.va_user_id<>json_extract(e.value,'$.vaUserId') OR l.player_id<>json_extract(e.value,'$.playerId')) AND NOT EXISTS(SELECT 1 FROM expected_players e LEFT JOIN league_players p ON p.id=json_extract(e.value,'$.playerId') WHERE json_extract(e.value,'$.newProfile')=0 AND (p.id IS NULL OR p.discord_name<>json_extract(e.value,'$.displayName'))) AND NOT EXISTS(SELECT 1 FROM expected_players e JOIN league_players p ON p.id=json_extract(e.value,'$.playerId') OR p.normalized_name=lower(trim(json_extract(e.value,'$.displayName'))) WHERE json_extract(e.value,'$.newProfile')=1)) THEN 1 ELSE json_extract('International roster changed since review', '$') END AS reviewed_roster_guard;
